+const HOLD_COMPAT_REPLY: &str = "LAMP_TEST_MEMORY_HOLD_COMPAT_REPLY";
+const RIGHT_AFTER: &str =
+    "voice::forget_that_right_after_a_follow_up_forgets_the_entry_it_was_about";
+const JOURNALLED: &str = "voice::forget_that_after_a_follow_up_leaves_nothing_of_its_conversation";
+const RETRIED: &str = "voice::a_refused_follow_up_forget_survives_the_next_turn_note_refresh";
+
+// Scratch-only observations. These timestamps never expose the client's private
+// lock/settlement state or remaining budget, and callback return is not a send ACK.
+struct Diagnostic {
+    origin: Instant,
+    case: &'static str,
+    branch: Value,
+    person: String,
+    events: Sender<Value>,
+    sequence: AtomicU64,
+    controlled: bool,
+    armed: AtomicBool,
+    entered_hold: AtomicBool,
+    invalid_hold: AtomicBool,
+    hold: Mutex<Option<Receiver<()>>>,
+}
+
+impl Diagnostic {
+    fn event(&self, phase: &str, at: Instant, details: Value) {
+        let _ = self.events.send(json!({
+            "case": self.case,
+            "branch": self.branch,
+            "controlled": self.controlled,
+            "phase": phase,
+            "at_us": at.duration_since(self.origin).as_micros(),
+            "details": details,
+        }));
+    }
+
+    fn answer(&self, sequence: u64, request: &Value, answer: &Answer) {
+        self.event(
+            "answer_ready",
+            Instant::now(),
+            json!({
+                "sequence": sequence,
+                "request": request,
+                "answer_line": answer.line,
+                "storage_fault": answer.storage_fault,
+                "wrote": answer.wrote,
+            }),
+        );
+    }
+
+    fn before_return(&self, sequence: u64, request: &Value) {
+        if request["op"] == "kept"
+            && request["observations"] == true
+            && request["person"].as_str() == Some(self.person.as_str())
+            && self.armed.swap(false, Ordering::AcqRel)
+        {
+            self.entered_hold.store(true, Ordering::Release);
+            self.event(
+                "compatibility_reply_hold_entered",
+                Instant::now(),
+                json!({
+                    "sequence": sequence, "request": request,
+                    "limit": "reachability only; earlier than the historical bare-forget log",
+                }),
+            );
+            let hold = self.hold.lock().unwrap().take().unwrap();
+            match hold.recv_timeout(Duration::from_secs(5)) {
+                Ok(()) => self.event(
+                    "compatibility_reply_explicitly_released",
+                    Instant::now(),
+                    json!({"sequence": sequence}),
+                ),
+                Err(error) => {
+                    self.invalid_hold.store(true, Ordering::Release);
+                    self.event(
+                        "INVALID_hold_cleanup",
+                        Instant::now(),
+                        json!({"sequence": sequence, "error": error.to_string()}),
+                    );
+                }
+            }
+        }
+        self.event(
+            "answer_returning",
+            Instant::now(),
+            json!({
+                "sequence": sequence, "request": request,
+                "meaning": "immediately before callback return; no socket/client acknowledgement",
+            }),
+        );
+    }
+}
+
 struct Traced {
     store: Days,
     trace: Sender<(Value, Value)>,
     hold: Option<Receiver<()>>,
     refuse_forget: bool,
+    diagnostic: Arc<OnceLock<Diagnostic>>,
 }

