+        let sequence = self.diagnostic.get().map(|diagnostic| {
+            let sequence = diagnostic.sequence.fetch_add(1, Ordering::Relaxed);
+            diagnostic.event(
+                "request_entered",
+                entered,
+                json!({"sequence": sequence, "request": request}),
+            );
+            sequence
+        });
         let answer = if self.refuse_forget && request["op"] == "forget" {
             self.refuse_forget = false;
             Answer {
@@ -57,10 +160,16 @@ impl Memory for Traced {
         } else {
