+
+    fn diagnose(&mut self, case: &'static str, person: &str, branch: Value) {
+        let controlled = std::env::var(HOLD_COMPAT_REPLY).ok().as_deref() == Some(case);
+        assert!(
+            self.diagnostic
+                .set(Diagnostic {
+                    origin: Instant::now(),
+                    case,
+                    branch,
+                    person: person.to_owned(),
+                    events: self.phase_sender.clone(),
+                    sequence: AtomicU64::new(0),
+                    controlled,
+                    armed: AtomicBool::new(false),
+                    entered_hold: AtomicBool::new(false),
+                    invalid_hold: AtomicBool::new(false),
+                    hold: Mutex::new(self.hold.take()),
+                })
+                .is_ok()
+        );
+    }
+
+    fn arm_compatibility_hold(&self) {
+        if let Some(diagnostic) = self.diagnostic.get()
+            && diagnostic.controlled
+        {
+            diagnostic.armed.store(true, Ordering::Release);
+            diagnostic.event(
+                "compatibility_hold_armed",
+                Instant::now(),
+                json!({"person": diagnostic.person}),
+            );
+        }
+    }
+
+    fn call_result(
+        &self,
+        attempt: &str,
+        times: (Instant, Instant),
+        request: &ToolCall,
+        result: (&Value, bool),
+    ) {
+        if let Some(diagnostic) = self.diagnostic.get() {
+            diagnostic.event(
+                "caller_returned",
+                times.1,
+                json!({
+                    "attempt": attempt,
+                    "started_us": times.0.duration_since(diagnostic.origin).as_micros(),
+                    "elapsed_us": times.1.duration_since(times.0).as_micros(),
+                    "call": {"id": request.id, "name": request.name, "args": request.args},
+                    "person": diagnostic.person, "deadline_ms": 1500,
+                    "return": [result.0, result.1],
+                    "private_remaining_budget": "unobserved",
+                    "private_settlement_and_context_lock": "unobserved",
+                }),
+            );
+        }
+    }
+
+    fn flush_phases(&self) {
+        for event in self.phases.try_iter() {
+            eprintln!("MEMORY_PHASE {event}");
+        }
+    }
+
+    fn finish(&mut self) -> Result<(), &'static str> {
+        let released = self.release.take().map(|release| release.send(()).is_ok());
+        let Some(worker) = self.worker.take() else {
+            return Ok(());
+        };
+        self.stop.stop();
+        let joined = worker.join().is_ok();
+        if let Some(diagnostic) = self.diagnostic.get() {
+            diagnostic.event(
+                "fixture_stopped_and_joined",
+                Instant::now(),
+                json!({
+                    "explicit_release_sent": released, "joined": joined,
+                    "hold_entered": diagnostic.entered_hold.load(Ordering::Acquire),
+                    "hold_invalid": diagnostic.invalid_hold.load(Ordering::Acquire),
+                }),
+            );
+        }
+        if joined {
+            Ok(())
+        } else {
+            Err("Memory fixture worker panicked")
+        }
+    }
+
+    fn finish_control(&mut self) {
+        if self
+            .diagnostic
+            .get()
+            .is_some_and(|diagnostic| diagnostic.controlled)
+        {
+            let finished = self.finish();
+            self.flush_phases();
+            let diagnostic = self.diagnostic.get().unwrap();
+            assert!(
+                finished.is_ok(),
+                "INVALID controlled fixture cleanup: {finished:?}"
+            );
+            assert!(
+                diagnostic.entered_hold.load(Ordering::Acquire),
+                "INVALID compatibility hold was not entered"
+            );
+            assert!(
+                !diagnostic.invalid_hold.load(Ordering::Acquire),
+                "INVALID compatibility hold ended without explicit release"
+            );
         }
     }

