 impl Drop for Fixture {
     fn drop(&mut self) {
-        self.stop.stop();
-        self.worker.take().unwrap().join().unwrap();
-        fs::remove_dir_all(&self.root).unwrap();
+        // Release before stop/join even during assertion unwind. The owned
+        // process watchdog bounds a stalled join; no helper thread is detached.
+        let finished = self.finish();
+        self.flush_phases();
+        let removed = fs::remove_dir_all(&self.root);
+        if std::thread::panicking() {
+            if finished.is_err() || removed.is_err() {
+                eprintln!(
+                    "INVALID Memory diagnostic cleanup during unwind: {finished:?}; {removed:?}"
+                );
+            }
+        } else {
+            finished.unwrap();
+            removed.unwrap();
+        }
     }
 }

